var PredefinedOp = class {
	constructor(predefinedOps, type) {
		this.predefinedOps = predefinedOps;
		this.type = type;
	}
	decode(stream, parent, operands) {
		if (this.predefinedOps[operands[0]]) return this.predefinedOps[operands[0]];
		return this.type.decode(stream, parent, operands);
	}
	size(value, ctx) {
		return this.type.size(value, ctx);
	}
	encode(stream, value, ctx) {
		let index = this.predefinedOps.indexOf(value);
		if (index !== -1) return index;
		return this.type.encode(stream, value, ctx);
	}
};
var CFFEncodingVersion = class extends r.Number {
	constructor() {
		super("UInt8");
	}
	decode(stream) {
		return r.uint8.decode(stream) & 127;
	}
};
