var RangeArray = class extends r.Array {
	decode(stream, parent) {
		let length = resolveLength(this.length, stream, parent);
		let count = 0;
		let res = [];
		while (count < length) {
			let range = this.type.decode(stream, parent);
			range.offset = count;
			count += range.nLeft + 1;
			res.push(range);
		}
		return res;
	}
};
