									c2y = c1y + stack.shift();
									c3x = c2x + stack.shift();
									c3y = c2y;
									c4x = c3x + stack.shift();
									c4y = c3y;
									c5x = c4x + stack.shift();
									c5y = c4y + stack.shift();
									c6x = c5x + stack.shift();
									c6y = c5y;
									x = c6x;
									y = c6y;
									path.bezierCurveTo(c1x, c1y, c2x, c2y, c3x, c3y);
